const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').split(/\s+/).filter(s => s.length > 0);

let idx = 0;
const M = parseInt(data[idx++]);
const N = parseInt(data[idx++]);

const stock = [];
for (let i = 0; i < M; i++) {
  const row = new Array(N);
  for (let j = 0; j < N; j++) {
    row[j] = parseInt(data[idx++]);
  }
  stock.push(row);
}

const P = parseInt(data[idx++]);
let sold = 0;

for (let p = 0; p < P; p++) {
  const i = parseInt(data[idx++]) - 1;
  const j = parseInt(data[idx++]) - 1;
  if (stock[i][j] > 0) {
    stock[i][j]--;
    sold++;
  }
}

console.log(sold);
